# Assuming there exists a helper function: calculate_stock_volatility(prices) -> float

def dummy_volatility(prices):
    # Dummy implementation
    return max(prices) - min(prices)

def portfolio_risk_assessment(stocks):
    '''
    Takes a dict where keys are stock names and values have 'prices' list and 'allocation' float.
    For each stock, call calculate_stock_volatility(prices), multiply by allocation, sum all weighted volatilities.
    Returns: float representing total portfolio risk as weighted sum.
    '''
    total = 0.0
    for stock, data in stocks.items():
        vol = dummy_volatility(data['prices'])
        total += vol * data['allocation']
    return total

