def calculate_stock_volatility(prices):
    # Simple dummy volatility: std deviation
    from statistics import stdev
    return stdev(prices) if len(prices) > 1 else 0.0

def portfolio_risk_assessment(portfolio):
    '''
    Given a portfolio dict with stock allocations and price lists,
    returns total portfolio risk as weighted sum of volatilities.
    '''
    total_risk = 0.0
    for stock, data in portfolio.items():
        prices = data['prices']
        allocation = data['allocation']
        volatility = calculate_stock_volatility(prices)
        total_risk += volatility * allocation
    return total_risk

